import { test, expect } from '@playwright/test';

test.describe('Payment Processing Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display loading state while payment is processing', async ({ page }) => {
    // Intercept the payment API call
    await page.route('**/api/payment/process', (route) => {
      route.continue();
    });

    // Verify loading indicator is visible
    const loadingIndicator = page.getByRole('status', { name: /processing/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Verify payment button is disabled
    const paymentButton = page.getByRole('button', { name: /submit payment/i });
    await expect(paymentButton).toBeDisabled();

    // Verify success message is not visible
    const successMessage = page.getByText(/successfully processed/i);
    await expect(successMessage).not.toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify payment details are visible
    const paymentDetails = page.getByRole('region', { name: /payment details/i });
    await expect(paymentDetails).toBeVisible();

    // Verify transaction ID is displayed
    const transactionId = page.getByText(/txn id: \d+/i);
    await expect(transactionId).toBeVisible();

    // Verify order summary is visible
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify order confirmation button is visible
    const orderConfirmationButton = page.getByRole('button', { name: /confirm order/i });
    await expect(orderConfirmationButton).toBeVisible();

    // Verify order confirmation button is disabled
    await expect(orderConfirmationButton).toBeDisabled();

    // Verify order details are displayed
    const orderDetails = page.getByRole('region', { name: /order details/i });
    await expect(orderDetails).toBeVisible();

    // Verify order status is loading
    const orderStatus = page.getByText(/order status: loading/i);
    await expect(orderStatus).toBeVisible();

    // Verify order status is updated to success
    const orderStatusText = page.getByText(/order status: completed/i);
    await expect(orderStatusText).toBeVisible();

    // Verify order confirmation button is now enabled
    await expect(orderConfirmationButton).not.toBeDisabled();

    // Verify order confirmation button is clickable
    await expect(orderConfirmationButton).toBeClickable();

    // Click order confirmation button
    await orderConfirmationButton.click();

    // Verify success message is now visible
    const successMessage = page.getByText(/order confirmed/i);
    await expect(successMessage).toBeVisible();

    // Verify payment button is now enabled
    await expect(paymentButton).not.toBeDisabled();

    // Verify order summary is updated
    const orderSummaryText = page.getByText(/order summary: $ /i);
    await expect(orderSummaryText).toBeVisible();

    // Verify order details are still visible
    await expect(orderDetails).toBeVisible();

    // Verify transaction ID is still displayed
    await expect(transactionId).toBeVisible();

    // Verify order status is now completed
    const orderStatusText = page.getByText(/order status: completed/i);
    await expect(orderStatusText).toBeVisible();

    // Verify order confirmation button is now disabled
    await expect(orderConfirmationButton).toBeDisabled();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();

    // Verify loading indicator is no longer visible
    const loadingIndicator = page.getByRole('status', { name: /processing/i });
    await expect(loadingIndicator).not.toBeVisible();
  });

  test('should display error state when payment fails', async ({ page }) => {
    // Intercept the payment API call with an error response
    await page.route('**/api/payment/process', (route) => {
      route.abort('failed');
    });

    // Verify error message is visible
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify loading indicator is not visible
    const loadingIndicator = page.getByRole('status', { name: /processing/i });
    await expect(loadingIndicator).not.toBeVisible();

    // Verify payment form is still visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Verify payment button is still disabled
    const paymentButton = page.getByRole('button', { name: /submit payment/i });
    await expect(paymentButton).toBeDisabled();

    // Verify error message is visible
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText(/successfully processed/i);
    await expect(successMessage).not.toBeVisible();

    // Verify error message contains error code
    const errorCode = page.getByText(/error code: \d+/i);
    await expect(errorCode).toBeVisible();

    // Verify order summary is still visible
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify order confirmation button is still disabled
    const orderConfirmationButton = page.getByRole('button', { name: /confirm order/i });
    await expect(orderConfirmationButton).toBeDisabled();

    // Verify order details are still visible
    const orderDetails = page.getByRole('region', { name: /order details/i });
    await expect(orderDetails).toBeVisible();

    // Verify order status is loading
    const orderStatus = page.getByText(/order status: loading/i);
    await expect(orderStatus).toBeVisible();

    // Verify order status is not updated to success
    const orderStatusText = page.getByText(/order status: failed/i);
    await expect(orderStatusText).toBeVisible();

    // Verify error message is still visible
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message is still visible
    const errorCode = page.getByText(/error code: \d+/i);
    await expect(errorCode).toBeVisible();

    // Verify payment button is still disabled
    await expect(paymentButton).toBeDisabled();

    // Verify order confirmation button is still disabled
    await expect(orderConfirmationButton).toBeDisabled();

    // Verify order summary is still visible
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify order details are still visible
    const orderDetails = page.getByRole('region', { name: /order details/i });
    await expect(orderDetails).toBeVisible();

    // Verify loading indicator is still not visible
    const loadingIndicator = page.getByRole('status', { name: /processing/i });
    await expect(loadingIndicator).not.toBeVisible();
  });
});
